<?php
declare(strict_types=1);

// Everything generated by ffmpeg lives in CACHE_DIR as "<cache key>.<kind>".

function cachePath(string $key, string $kind): string
{
    return CACHE_DIR . '/' . $key . '.' . $kind;
}

/**
 * Creates $target (file or directory) once, even when several requests ask at the same time.
 * $build receives a temporary path to write to and returns success; it is then moved into place.
 */
function buildOnce(string $target, callable $build): bool
{
    if (file_exists($target)) {
        return true;
    }
    ignore_user_abort(true); // finish and cache even if the viewer moves on
    set_time_limit(0);
    $lock = @fopen(lockPath($target), 'c');
    if ($lock === false) {
        return false;
    }
    flock($lock, LOCK_EX); // a second request for the same target waits for the first
    if (!file_exists($target)) {
        $tmp = $target . '.tmp';
        removePath($tmp);
        if ($build($tmp)) {
            rename($tmp, $target);
        } else {
            removePath($tmp);
        }
    }
    flock($lock, LOCK_UN);
    fclose($lock);
    return file_exists($target);
}

/**
 * Lock file for buildOnce($target). Not next to the target: flock() silently does nothing on the
 * cache folder (a macOS bind mount in Docker Desktop), so two requests would build the same file
 * at once. The container's own /tmp locks properly, and only this container builds. Lock files
 * are kept, not deleted: removing one while another request waits on it would let a third
 * request lock a new file and build alongside the second.
 */
function lockPath(string $target): string
{
    $dir = sys_get_temp_dir() . '/vid-locks';
    if (!is_dir($dir)) {
        @mkdir($dir, 0777, true);
    }
    return $dir . '/' . sha1($target) . '.lock';
}

function removePath(string $path): void
{
    if (is_dir($path)) {
        foreach (glob($path . '/*') ?: [] as $file) {
            @unlink($file);
        }
        @rmdir($path);
    } elseif (file_exists($path)) {
        @unlink($path);
    }
}
